mapper.select:
SELECT
    ,



    t.is_deleted = 0


        AND (t.activity_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR t.title LIKE CONCAT('%', #{q.keyword}, '%'))


        AND t.position_type = #{q.positionType}


        AND t.activity_type = #{q.activityType}


        AND t.status = #{q.status}




        AND t.start_time >= #{q.startFrom}


        AND t.start_time <= #{q.startTo}



ORDER BY t.weight DESC, t.id DESC
